          "n": 1,
          "page": 1,
          "scene": "The third-floor room at night. Moonlight from a high slit. A huge brown three-headed dog fills a wooden trapdoor, collars on, drooling. The left head is heavy-eyed, the middle head still suspicious, the right head yawning. Harry plays a small wooden flute, badly. Small music notes travel from the flute to all three heads. Sleepy heads have heavy half-closed lids and a small Zzz. Awake heads do not get Zzz. Hermione and Ron press in behind him with lit wands.",
          "expressions": "Harry looks at the heads, concentrated, a boy who will not stop. The middle head looks at him, then glassy. Hermione watches the paws. Ron looks at the teeth and stays.",
          "caption": "Harry plays, badly. The heads droop.",
          "dialogue": [
            {
              "who": "Harry",
              "line": "It's meant to be a lullaby. Please work."
            },
            {
              "who": "Hermione",
              "line": "One head is down. Don't stop."
            }
          ],
          "art": "art/c17-p1-p1.jpg"
